205	EvaluateExpressionOptions
206	CommandObjectExpression::CommandOptions::GetEvaluateExpressionOptions(
207	    const Target &target, const OptionGroupValueObjectDisplay &display_opts) {
208	  EvaluateExpressionOptions options;
209	  options.SetCoerceToId(display_opts.use_object_desc);
210	  options.SetUnwindOnError(unwind_on_error);
211	  options.SetIgnoreBreakpoints(ignore_breakpoints);
212	  options.SetKeepInMemory(true);
213	  options.SetUseDynamic(display_opts.use_dynamic);
214	  options.SetTryAllThreads(try_all_threads);
215	  options.SetDebug(debug);
216	  options.SetLanguage(language);
217	  options.SetExecutionPolicy(
218	      allow_jit ? EvaluateExpressionOptions::default_execution_policy
219	                : lldb_private::eExecutionPolicyNever);
220	  options.SetCppIgnoreContextQualifiers(cpp_ignore_context_qualifiers);
221	
222	  bool auto_apply_fixits;
223	  if (this->auto_apply_fixits == eLazyBoolCalculate)
224	    auto_apply_fixits = target.GetEnableAutoApplyFixIts();
225	  else
226	    auto_apply_fixits = this->auto_apply_fixits == eLazyBoolYes;
227	
228	  options.SetAutoApplyFixIts(auto_apply_fixits);
229	  options.SetRetriesWithFixIts(target.GetNumberOfRetriesWithFixits());
230	
231	  if (top_level)
232	    options.SetExecutionPolicy(eExecutionPolicyTopLevel);
233	
234	  // If there is any chance we are going to stop and want to see what went
235	  // wrong with our expression, we should generate debug info
236	  if (!ignore_breakpoints || !unwind_on_error)
237	    options.SetGenerateDebugInfo(true);
238	
239	  if (timeout > 0)
240	    options.SetTimeout(std::chrono::microseconds(timeout));
241	  else
242	    options.SetTimeout(std::nullopt);
243	  return options;
244	}
