246	bool CommandObjectExpression::CommandOptions::ShouldSuppressResult(
247	    const OptionGroupValueObjectDisplay &display_opts) const {
248	  // Explicitly disabling persistent results takes precedence over the
249	  // m_verbosity/use_object_desc logic.
250	  if (suppress_persistent_result != eLazyBoolCalculate)
251	    return suppress_persistent_result == eLazyBoolYes;
252	
253	  return display_opts.use_object_desc &&
254	         m_verbosity == eLanguageRuntimeDescriptionDisplayVerbosityCompact;
255	}
