257	CommandObjectExpression::CommandObjectExpression(
258	    CommandInterpreter &interpreter)
259	    : CommandObjectRaw(interpreter, "expression",
260	                       "Evaluate an expression on the current "
261	                       "thread.  Displays any returned value "
262	                       "with LLDB's default formatting.",
263	                       "",
264	                       eCommandProcessMustBePaused | eCommandTryTargetAPILock |
265	                           eCommandAllowsDummyTarget),
266	      IOHandlerDelegate(IOHandlerDelegate::Completion::Expression),
267	      m_format_options(eFormatDefault),
268	      m_repl_option(LLDB_OPT_SET_1, false, "repl", 'r', "Drop into REPL", false,
269	                    true),
270	      m_expr_line_count(0) {
271	  SetHelpLong(
272	      R"(
273	Single and multi-line expressions:
274	
275	)"
276	      "    The expression provided on the command line must be a complete expression \
277	with no newlines.  To evaluate a multi-line expression, \
278	hit a return after an empty expression, and lldb will enter the multi-line expression editor. \
279	Hit return on an empty line to end the multi-line expression."
280	
281	      R"(
282	
283	Timeouts:
284	
285	)"
286	      "    If the expression can be evaluated statically (without running code) then it will be.  \
287	Otherwise, by default the expression will run on the current thread with a short timeout: \
288	currently .25 seconds.  If it doesn't return in that time, the evaluation will be interrupted \
289	and resumed with all threads running.  You can use the -a option to disable retrying on all \
290	threads.  You can use the -t option to set a shorter timeout."
291	      R"(
292	
293	User defined variables:
294	
295	)"
296	      "    You can define your own variables for convenience or to be used in subsequent expressions.  \
297	You define them the same way you would define variables in C.  If the first character of \
298	your user defined variable is a $, then the variable's value will be available in future \
299	expressions, otherwise it will just be available in the current expression."
300	      R"(
301	
302	Continuing evaluation after a breakpoint:
303	
304	)"
305	      "    If the \"-i false\" option is used, and execution is interrupted by a breakpoint hit, once \
306	you are done with your investigation, you can either remove the expression execution frames \
307	from the stack with \"thread return -x\" or if you are still interested in the expression result \
308	you can issue the \"continue\" command and the expression evaluation will complete and the \
309	expression result will be available using the \"thread.completed-expression\" key in the thread \
310	format."
311	
312	      R"(
313	
314	Examples:
315	
316	    expr my_struct->a = my_array[3]
317	    expr -f bin -- (index * 8) + 5
318	    expr unsigned int $foo = 5
319	    expr char c[] = \"foo\"; c[0])");
320	
321	  AddSimpleArgumentList(eArgTypeExpression);
322	
323	  // Add the "--format" and "--gdb-format"
324	  m_option_group.Append(&m_format_options,
325	                        OptionGroupFormat::OPTION_GROUP_FORMAT |
326	                            OptionGroupFormat::OPTION_GROUP_GDB_FMT,
327	                        LLDB_OPT_SET_1);
328	  m_option_group.Append(&m_command_options);
329	  m_option_group.Append(&m_varobj_options, LLDB_OPT_SET_ALL,
330	                        LLDB_OPT_SET_1 | LLDB_OPT_SET_2);
331	  m_option_group.Append(&m_repl_option, LLDB_OPT_SET_ALL, LLDB_OPT_SET_3);
332	  m_option_group.Finalize();
333	}
